/**
 * Extract matric number from student email or matric string
 * e.g. "ap05710@siswa.ukm.edu.my" -> "AP05710"
 * or "AP05710" -> "AP05710"
 */
export function extractMatricNumber(input: string): string {
  if (!input) return '';
  const trimmed = input.trim();
  const prefix = trimmed.includes('@') ? trimmed.split('@')[0] : trimmed;
  return prefix.toUpperCase();
}

/**
 * Look up student by either email, matric number, or partial prefix
 */
export function findStudentInRoster(query: string): StudentRosterItem | undefined {
  if (!query) return undefined;
  const clean = query.trim().toLowerCase();
  const matric = extractMatricNumber(clean);

  return OFFICIAL_318_STUDENTS_ROSTER.find(
    (s) =>
      s.email.toLowerCase() === clean ||
      s.matricNumber.toUpperCase() === matric ||
      s.matricNumber.toLowerCase() === clean
  );
}
